public class Solution {
    public static void main(String[] args) {
        int[] values = {10, -5, 20, -8, 25, 30};
        int sum = 0;
        int threshold = 50;

        for (int v : values) {
            if (v < 0) {
                continue; // Ignore negative amounts
            }
            sum += v;
            if (sum >= threshold) {
                System.out.println("Threshold reached (" + sum + " >= " + threshold + "). Halting.");
                break;
            }
        }

        System.out.println("Final running sum: " + sum);
    }
}

