public class Solution {
    public static void main(String[] args) {
        int[] numbers = {1, 4, 20, 3, 10, 5};
        int target = 33;
        int start = -1, end = -1;
        boolean found = false;

        outer:
        for (int i = 0; i < numbers.length; i++) {
            int currentSum = 0;
            for (int j = i; j < numbers.length; j++) {
                currentSum += numbers[j];
                if (currentSum == target) {
                    start = i;
                    end = j;
                    found = true;
                    break outer;
                }
                if (currentSum > target) {
                    break; // Prune: sum already exceeds target
                }
            }
        }

        System.out.println("Target sum: " + target);
        System.out.println("Subarray found: " + found);
        if (found) {
            System.out.println("Window indices: [" + start + " to " + end + "]");
        }
    }
}

public class Solution {
    public static int findSubstring(String text, String pattern) {
        int n = text.length();
        int m = pattern.length();

        for (int i = 0; i <= n - m; i++) {
            int j = 0;
            for (; j < m; j++) {
                if (text.charAt(i + j) != pattern.charAt(j)) {
                    break; // Mismatch detected; abort check at offset i
                }
            }
            if (j == m) {
                return i; // Full match found
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        String text = "JavaProgrammingLanguage";
        String pattern = "Program";
        int pos = findSubstring(text, pattern);
        System.out.println("Text: " + text);
        System.out.println("Pattern: " + pattern);
        System.out.println("Pattern found at offset: " + pos);
    }
}

public class Solution {
    public static void main(String[] args) {
        int initialBalance = 100;
        int balance = initialBalance;
        int[] ledgerDeltas = {50, -30, -150, 40};
        boolean aborted = false;
        int failedIndex = -1;

        txBlock:
        for (int i = 0; i < ledgerDeltas.length; i++) {
            int delta = ledgerDeltas[i];
            if (balance + delta < 0) {
                aborted = true;
                failedIndex = i;
                break txBlock; // Abort transaction batch
            }
            balance += delta;
        }

        if (aborted) {
            System.out.println("Transaction " + failedIndex + " failed (insufficient balance). Rolling back.");
            balance = initialBalance; // Rollback to snapshot
        }
        System.out.println("Final Account Balance: $" + balance);
    }
}

import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static void main(String[] args) {
        String expr = "142 + 58 * 3";
        List<String> tokens = new ArrayList<>();
        int i = 0;
        boolean valid = true;

        while (i < expr.length()) {
            char ch = expr.charAt(i);
            if (Character.isWhitespace(ch)) {
                i++;
                continue;
            }
            if (ch == '+' || ch == '-' || ch == '*' || ch == '/') {
                tokens.add(String.valueOf(ch));
                i++;
                continue;
            }
            if (Character.isDigit(ch)) {
                StringBuilder num = new StringBuilder();
                while (i < expr.length() && Character.isDigit(expr.charAt(i))) {
                    num.append(expr.charAt(i));
                    i++;
                }
                tokens.add(num.toString());
                continue;
            }
            valid = false;
            break;
        }

        System.out.println("Expression: " + expr);
        if (valid) {
            System.out.println("Tokens: " + tokens);
        } else {
            System.out.println("Lexing Error: Invalid character encountered.");
        }
    }
}
